from __future__ import annotations
from math import exp, log
from typing import Sequence

def normalized_exp_log(xs: Sequence[float], a: float, b: float) -> list[float]:
    raw = [exp(a) * log(1.0 + b*x) for x in xs]
    total = sum(raw)
    return [w / total for w in raw]

def main() -> None:
    xs = [0.5, 1.0, 2.0, 4.0]
    for a in [-20.0, -5.0, 0.0, 5.0, 20.0]:
        print(a, normalized_exp_log(xs, a, 0.8))

if __name__ == "__main__":
    main()

