from __future__ import annotations
from typing import Sequence

def audit_fisher(probabilities: Sequence[float], shape_scores: Sequence[float]) -> dict[str, object]:
    if len(probabilities) != len(shape_scores): raise ValueError("length mismatch")
    ibb=sum(p*s*s for p,s in zip(probabilities,shape_scores))
    matrix=((0.0,0.0),(0.0,ibb))
    return {"matrix": matrix, "determinant": 0.0, "rank": 1 if ibb > 0.0 else 0}

